import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Platform abstractions and plugin system","description":"","frontmatter":{"title":"Platform abstractions and plugin system","type":"adr","date":"2026-08-25T00:00:00.000Z","status":"proposed","status_note":"Proposed"},"headers":[],"relativePath":"handl/project/adrs/0031-platform-abstractions.md","filePath":"vendored/handl/project/adrs/0031-platform-abstractions.md"}`),a={name:`handl/project/adrs/0031-platform-abstractions.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0031-platform-abstractions-and-plugin-system" tabindex="-1">ADR 0031: Platform abstractions and plugin system <a class="header-anchor" href="#adr-0031-platform-abstractions-and-plugin-system" aria-label="Permalink to “ADR 0031: Platform abstractions and plugin system”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Introduce a single new crate <code>handl-platform</code> that contains the core platform contracts as modules. No separate <code>handl-plugin</code>, <code>handl-extension</code>, or <code>handl-framework</code> crates for now.</p><p>The <code>handl-platform</code> modules are:</p><ul><li><code>capability</code> — <code>Capability</code>, <code>CapabilityId</code>, <code>CapabilityMetadata</code></li><li><code>plugin</code> — <code>Plugin</code>, <code>PluginManifest</code>, <code>PluginRegistry</code>, <code>InProcessPlugin</code>, <code>ProcessPlugin</code></li><li><code>extension</code> — <code>Extension</code>, <code>ExtensionMetadata</code></li><li><code>kit</code> — <code>Kit</code>, <code>KitManifest</code>, <code>KitRegistry</code></li><li><code>host</code> — <code>Host</code></li><li><code>boundary</code> — <code>Boundary</code>, <code>BoundaryKind</code></li></ul><p><code>CapabilityMetadata</code> is any JSON-serializable object. The platform layer does not define CLI-specific keys such as <code>command</code> or <code>aliases</code>. It is exposed as an opaque <code>serde_json::Value</code> so hosts can interpret it independently:</p><div class="language-rust"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">pub</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> type</span><span style="--shiki-dark:#C5C5C5;--shiki-light:#6F42C1;"> CapabilityMetadata</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> =</span><span style="--shiki-dark:#0FF;--shiki-dark-font-weight:bold;--shiki-light:#6F42C1;--shiki-light-font-weight:inherit;"> serde_json</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">::</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">Value</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">;</span></span></code></pre></div><p>A plugin may return metadata like:</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#888888;--shiki-light:#24292E;">{</span></span>
<span class="line"><span style="--shiki-dark:#888888;--shiki-light:#005CC5;">  &quot;</span><span style="--shiki-dark:#C5C5C5;--shiki-light:#005CC5;">command</span><span style="--shiki-dark:#888888;--shiki-light:#005CC5;">&quot;</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;"> &quot;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">compile</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">,</span></span>
<span class="line"><span style="--shiki-dark:#888888;--shiki-light:#005CC5;">  &quot;</span><span style="--shiki-dark:#C5C5C5;--shiki-light:#005CC5;">description</span><span style="--shiki-dark:#888888;--shiki-light:#005CC5;">&quot;</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;"> &quot;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">Compile a Handl module</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">,</span></span>
<span class="line"><span style="--shiki-dark:#888888;--shiki-light:#005CC5;">  &quot;</span><span style="--shiki-dark:#C5C5C5;--shiki-light:#005CC5;">aliases</span><span style="--shiki-dark:#888888;--shiki-light:#005CC5;">&quot;</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;"> [</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">build</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">]</span></span>
<span class="line"><span style="--shiki-dark:#888888;--shiki-light:#24292E;">}</span></span></code></pre></div><p>The <code>handl-host-cli</code> host may read the <code>command</code> field from this object and use it to generate a <code>clap</code> subcommand, but it does not require or hard-code any specific schema. Other hosts (LSP, web UI, CI) may surface the same capability using different fields.</p><h3 id="built-in-default-capabilities" tabindex="-1">Built-in default capabilities <a class="header-anchor" href="#built-in-default-capabilities" aria-label="Permalink to “Built-in default capabilities”">​</a></h3><p>The platform ships with a set of default capability crates named <code>handl-ext-{name}</code>. Each crate is a regular plugin that implements one capability and is pre-registered by the default <code>Host</code>:</p><ul><li><code>handl-ext-fmt</code></li><li><code>handl-ext-lint</code></li><li><code>handl-ext-typecheck</code></li><li><code>handl-ext-eval</code></li><li><code>handl-ext-compile</code></li><li><code>handl-ext-build</code></li><li><code>handl-ext-extension</code> — manages extensions (<code>add</code>, <code>remove</code>, <code>info</code>)</li><li><code>handl-ext-kit</code> — manages kits (<code>add</code>, <code>remove</code>, <code>info</code>)</li><li><code>handl-ext-plugin</code> — manages plugins (<code>add</code>, <code>remove</code>, <code>info</code>)</li></ul><p>These crates are the only place where concrete command semantics live. The <code>handl-host-cli</code> binary does not know about <code>fmt</code>, <code>lint</code>, <code>plugin</code>, etc. It loads the default <code>Host</code>, reads <code>CapabilityMetadata</code> from the registry, and generates subcommands from whatever the metadata contains.</p><p>The management capabilities (<code>extension</code>, <code>kit</code>, <code>plugin</code>) operate on the platform registries defined in <code>handl-platform</code>. They are not special-cased in the CLI.</p><h3 id="existing-crate-migrations" tabindex="-1">Existing crate migrations <a class="header-anchor" href="#existing-crate-migrations" aria-label="Permalink to “Existing crate migrations”">​</a></h3><ul><li><code>crates/host-cli-plugin</code> is emptied; its <code>PluginRegistry</code> and <code>CliPlugin</code> logic move into <code>handl-platform::plugin</code> and are generalized.</li><li><code>crates/compiler-pass-*</code> become pass hosts that use the platform <code>Plugin</code>/<code>Capability</code> traits to run a <code>Vec&lt;Box&lt;dyn Pass&gt;&gt;</code> assembled by <code>handl-compiler</code>.</li><li><code>crates/vm</code> / <code>crates/plugin-vm-host-eval</code> align their <code>Host</code> with <code>handl-platform::host</code>.</li></ul><h3 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to “Out of scope”">​</a></h3><p>For now we intentionally defer <code>Framework</code>, <code>Middleware</code>, <code>Rpc</code>, and the <code>handl-document</code> unification work described in ADRs 0028/0030. They can be added once the platform layer is stable.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>The Handl repository has grown a large number of small crates (<code>handl-ast</code>, <code>handl-vm</code>, <code>handl-compiler</code>, <code>handl-host-cli-plugin</code>, etc.) but it does not yet have a single, stable platform layer that defines how capabilities, plugins, extensions, hosts, and boundaries compose. Existing ADRs 0028, 0029, and 0030 describe pluggable composition, the CLI as a capability orchestrator, and a <code>lib-lang</code> façade, but they leave the platform contract undefined.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li>none recorded — legacy record; the design doc lists what was deferred.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>A single, small crate owns all platform contracts, making dependency direction explicit: everything else depends on <code>handl-platform</code>.</li><li>The CLI becomes a pure metadata-driven host. New capabilities appear automatically when a plugin registers them.</li><li>Built-in commands (<code>fmt</code>, <code>lint</code>, <code>plugin</code>, <code>kit</code>, etc.) are implemented as ordinary capability plugins, not as CLI code.</li><li>The compiler pipeline can be assembled from plugins without the compiler knowing the concrete pass implementations.</li><li>Stale <code>docs/api/ac_*</code> documentation and the <code>Peregrin.toml</code> reference can be removed as part of this work.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li>Code and tests are named in the design doc.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The full record (context, tables, phases, trade-offs): <a href="./../design/0031-platform-abstractions.html"><code>design/0031-platform-abstractions.md</code></a>.</p>`,29)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};